(() => {
 const grade=document.querySelector('#download-grade'),language=document.querySelector('#download-language'),subject=document.querySelector('#download-subject');
 const selected=()=>bilingualActivities.filter(a=>a.grade===grade.value&&(subject.value==='all'||a.subject===subject.value));
 function update(){document.querySelector('#pack-description').textContent=`Grade ${grade.value} · ${language.value==='en'?'English':'Sepedi'} · ${selected().length} activities in this pack`;}
 const esc=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function download(answers){const lang=language.value;const l=lang==='en'?{grade:'Grade',title:answers?'Answers and guidance':'Practice worksheet',print:'Print / Save as PDF',note:'Supplementary practice. Sepedi translations await fluent teacher review. Work with an adult where needed.',answer:'Answer or guidance'}:{grade:'Mphato wa',title:answers?'Dikarabo le tlhahlo':'Letlakala la go itlwaetša',print:'Gatiša / Boloka bjalo ka PDF',note:'Mošomo wa tlaleletšo. Diphetolelo tša Sepedi di emetše tekolo ya morutiši.',answer:'Karabo goba tlhahlo'};const html=`<!doctype html><html lang="${lang}"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>${l.grade} ${grade.value} ${l.title}</title><style>body{font:17px/1.7 Arial;max-width:800px;margin:30px auto;padding:20px;color:#174c2e}article{break-inside:avoid;padding:20px 0;border-top:1px solid #bbb}.answer-space{height:100px;border-bottom:1px dotted #aaa}button{padding:12px}@media print{button{display:none}body{margin:0;color:black}}</style><body><p>Diopong Primary School</p><h1>${l.grade} ${grade.value}: ${l.title}</h1><p>${l.note}</p><button onclick="window.print()">${l.print}</button>${selected().map((a,i)=>`<article><h2>${i+1}. ${esc(a.title[lang])}</h2><p>${esc(a.task[lang])}</p>${answers?`<p><strong>${l.answer}:</strong> ${esc(a.answer[lang])}</p>`:'<div class="answer-space"></div>'}</article>`).join('')}</body></html>`;const url=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`Diopong-Grade-${grade.value}-${lang}-${answers?'answers':'worksheet'}.html`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 [grade,language,subject].forEach(x=>x.addEventListener('change',update));document.querySelector('#download-worksheet').addEventListener('click',()=>download(false));document.querySelector('#download-memo').addEventListener('click',()=>download(true));update();
})();
